class Solution {
  public int minArea(char[][] image, int x, int y) {
    int m = image.length, n = image[0].length;
    // columns [0, y] go empty -> has a one, columns [y, n - 1] go has a one -> empty
    int lo = 0, hi = y;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (columnHasOne(image, mid)) hi = mid;
      else lo = mid + 1;
    }
    int left = lo;
    lo = y;
    hi = n - 1;
    while (lo < hi) {
      int mid = (lo + hi + 1) >>> 1;
      if (columnHasOne(image, mid)) lo = mid;
      else hi = mid - 1;
    }
    int right = lo;
    lo = 0;
    hi = x;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (rowHasOne(image, mid)) hi = mid;
      else lo = mid + 1;
    }
    int top = lo;
    lo = x;
    hi = m - 1;
    while (lo < hi) {
      int mid = (lo + hi + 1) >>> 1;
      if (rowHasOne(image, mid)) lo = mid;
      else hi = mid - 1;
    }
    int bottom = lo;
    return (right - left + 1) * (bottom - top + 1);
  }

  private boolean columnHasOne(char[][] image, int c) {
    for (char[] row : image) if (row[c] == '1') return true;
    return false;
  }

  private boolean rowHasOne(char[][] image, int r) {
    for (char ch : image[r]) if (ch == '1') return true;
    return false;
  }
}
